import{z as s,x as B,o as e,c as d,q as A,j as i,D as E,d as t,s as n,S as o,b as l}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"多模态 RLHF","description":"","frontmatter":{"title":"多模态 RLHF","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/multimodal-rlhf.md","filePath":"llm/multimodal-rlhf.md","lastUpdated":1791413859000}'),p={name:"llm/multimodal-rlhf.md"};function m(R,a,h,u,F,L){const r=B("Mermaid");return e(),d("div",null,[a[2]||(a[2]=A('<h1 id="多模态-rlhf" tabindex="-1">多模态 RLHF <a class="header-anchor" href="#多模态-rlhf" aria-label="Permalink to &quot;多模态 RLHF&quot;">​</a></h1><div class="epigraph"><p>比较现在发生在图文对上：奖励模型必须看见图像，否则策略会优化说明文字去骗一个盲的裁判。</p><footer>—— 对照 InstructGPT 的文本 RLHF；LLaVA / InstructBLIP 的视觉指令；GPT-4V 一类产品的图文偏好</footer></div><p><a href="/llm/honesty-calibration-training">上一课</a>的事实轴在纯文本上已难。配上图像，幻觉变成「描述了图里没有的物体」。缺口是：<strong><a href="/llm/rlhf-pipeline">RLHF</a> 的 RM、PPO、DPO 都要改输入为 \\((x_{\\text{img}},x_{\\text{txt}},y)\\)，比较协议也要防盲裁判。</strong> 本课写多模态偏好，不重写视觉编码器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>文本 RM 看不到图，会按说明文的流畅与长度打分。策略学会写华丽但与图无关的 \\(y\\)。必须：奖励器吃图像；或可验证轴（VQA 对错、定位框、OCR 核对）。人类比较要同时展示图与两条回答，标注员疲劳比文本高，偏差更大。</p><p><span class="marginnote">「奖励模型」就是一个学会了模仿人类偏好的打分器：给（图、问题、回答）三元组打一个分，RL 拿这个分当优化目标去抬高分。多模态的关键差别是打分器必须真的看到图——看不到图，它就只剩文笔可评。</span></p><p>视觉指令微调（LLaVA 等）多数停在 SFT。RLHF 层更少公开细节。原则与文本相同：比较→可选 RM→在线优化；差别是模态对齐与代价。</p><h3 id="盲裁判是静默故障" tabindex="-1">盲裁判是静默故障 <a class="header-anchor" href="#盲裁判是静默故障" aria-label="Permalink to &quot;盲裁判是静默故障&quot;">​</a></h3><p>用纯文本 LLM 当 <a href="/llm/llm-judge-reward">LLM 裁判</a> 评图文回答，等于上一课的盲 RM。必须用视觉裁判或把图转成不受策略控制的描述（仍有信息损失）。评测 MMMU 等有金标的题应走对错，不要走盲 Arena。</p><p><span class="marginnote">直觉类比：让只听录音的裁判给花样滑冰打分——他只能评音乐与解说，动作完成度全靠猜。策略很快发现「把解说写得华丽」比「把动作跳好」更容易拿分，于是只练解说。盲裁判的失效就是这样静默发生的。</span></p><p><span class="marginnote">安全：图像可把有害请求藏进像素。拒绝训练要含图，纯文本安全 RM 不够。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据：同一图下两条回答排序；或 VQA 可验证 \\(R\\)。RM：视觉编码器 + 语言模型 + 标量头，初始化自视觉 SFT。PPO：动作仍是文本 token，状态含图前缀，KL 拴视觉 SFT。DPO：对上同样带图前向。多目标：描述忠实（可与图核对的轴）硬门，文笔加权。</p>',13)),(e(),i(o,null,{default:E(()=>[n(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E5%9B%BE%E5%83%8F%20%2B%20%E6%8F%90%E7%A4%BA%22%5D%20--%3E%20Y%5B%22%E6%96%87%E6%9C%AC%E5%9B%9E%E7%AD%94%22%5D%0A%20%20IMG%20--%3E%20RM%5B%22%E8%A7%86%E8%A7%89%20RM%20%2F%20%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20Y%20--%3E%20RM%0A%20%20RM%20--%3E%20PPO%5B%22PPO%20%2F%20DPO%22%5D%0A%20%20BLIND%5B%22%E7%BA%AF%E6%96%87%E6%9C%AC%E8%A3%81%E5%88%A4%22%5D%20--%3E%20FAIL%5B%22%E4%BC%98%E5%8C%96%E4%B8%8E%E5%9B%BE%E6%97%A0%E5%85%B3%E7%9A%84%E6%96%87%E7%AC%94%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("p",null,"诚实：对「图中是否有 X」用可核对标签；不知则说看不清。校准图与文本分轴报。",-1)),a[4]||(a[4]=l("h2",{id:"机制",tabindex:"-1"},[t("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=l("p",null,"梯度通过语言头回流；视觉编码器通常冻或小学习率，否则 RL 破坏感知。过优化表现为：过长 OCR 式罗列、或讨好盲评测的模板句。金标必须是看图的人或题。视频与多图是同一逻辑，序列更长，截断与过长过滤同样适用。",-1)),a[6]||(a[6]=l("p",null,[l("span",{class:"marginnote"},"初学者容易以为「全部一起训」总是更好。实际上 RL 的奖励信号又稀疏又带噪，全量更新视觉编码器时，梯度会为迎合奖励而挪动感知表示——模型开始「看成」模板句需要的物体。冻结（或给很小的学习率）是让 RL 只改「怎么表达」，不动「看见什么」。")],-1)),(e(),i(o,null,{default:E(()=>[n(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20P%5B%22PPO%20%E6%A2%AF%E5%BA%A6%22%5D%20--%3E%20V%7B%22%E8%A7%86%E8%A7%89%E7%BC%96%E7%A0%81%E5%99%A8%E6%98%AF%E5%90%A6%E6%9B%B4%E6%96%B0%3F%22%7D%0A%20%20V%20--%3E%7C%22%E5%85%A8%E9%87%8F%E6%9B%B4%E6%96%B0%22%7C%20BR%5B%22%E6%84%9F%E7%9F%A5%E8%A1%A8%E7%A4%BA%E8%A2%AB%E5%A5%96%E5%8A%B1%E4%BF%A1%E5%8F%B7%E6%8B%96%E6%AD%AA%22%5D%0A%20%20BR%20--%3E%20H%5B%22%E5%BC%80%E5%A7%8B%E7%BC%96%E9%80%A0%E6%A8%A1%E6%9D%BF%E5%8F%A5%E9%9C%80%E8%A6%81%E7%9A%84%E7%89%A9%E4%BD%93%22%5D%0A%20%20V%20--%3E%7C%22%E5%86%BB%E7%BB%93%E6%88%96%E6%9E%81%E5%B0%8F%E5%AD%A6%E4%B9%A0%E7%8E%87%22%7C%20ST%5B%22%E6%84%9F%E7%9F%A5%E4%BF%9D%E6%8C%81%E7%A8%B3%E5%AE%9A%22%5D%0A%20%20ST%20--%3E%20OK%5B%22RL%20%E5%8F%AA%E4%BC%98%E5%8C%96%E8%AF%AD%E8%A8%80%E5%A4%B4%E7%9A%84%E8%A1%A8%E8%BE%BE%E6%96%B9%E5%BC%8F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p><span class="marginnote">工具调用看图 API 时，RL 的 \\(R\\) 应含工具返回是否被忠实转述，否则又编像素。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>无视觉 RM 预算时，只做视觉 SFT + 文本 RL，图文忠实会退步，应在评测里坦白。分辨率、裁剪、与训练时视觉预处理必须锁定，否则 RM 看见的图与策略看见的图不是同一张。下一课代码 SWE 环境是另一模态：状态是仓库与终端，不是像素，但「奖励必须看见环境」同一原则。</p><p>视觉预处理与 RM 入图分辨率要锁定。纯文本裁判评图文回答等于盲 RM，策略会写与像素无关的文笔。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多模态 RLHF 的奖励器必须看见图像，否则策略骗盲裁判。</li><li>有金标的 VQA / OCR 走可验证；开放描述才走视觉比较。</li><li>视觉编码器多冻；过优化是罗列与模板句。</li><li>图像安全与拒绝要含像素输入。</li><li>出处：Ouyang 文本 RLHF 骨架；Liu 等 LLaVA；Dai 等 InstructBLIP；视觉评测基准作金标。</li></ul>',6))])}const C=s(p,[["render",m]]);export{P as __pageData,C as default};
